// Method: Control::force_drag
static JSValue js_Control_force_drag(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "Control.force_drag: missing handle argument");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "Control.force_drag: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    // Check WRITE rate limit (PRD Section 6.4)
    ExecutionLimiter* limiter = qjs_ctx->get_execution_limiter();
    if (limiter && !limiter->check_api_rate_limit(ApiCategory::WRITE)) {
        return JS_ThrowInternalError(ctx, "Control.force_drag: write rate limit exceeded");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "Control.force_drag: invalid or freed object");
    }

    Control* typed_obj = Object::cast_to<Control>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "Control.force_drag: object is not a Control");
    }

    // Argument count check (excluding handle) - only required args
    if (argc < 3) {
        return JS_ThrowTypeError(ctx, "Control.force_drag: expected at least 2 arguments, got %d", argc - 1);
    }

    // Convert arguments
    Variant arg_data = qjs_ctx->js_to_variant(argv[1]);
    Control* arg_preview = nullptr;
    if (JS_IsNumber(argv[2])) {
        // Direct handle (unwrapped by JS proxy)
        int64_t h_preview; JS_ToInt64(ctx, &h_preview, argv[2]);
        Object* obj_preview = qjs_ctx->get_object_registry()->get_object(h_preview);
        arg_preview = reinterpret_cast<Control*>(obj_preview);
    } else {
        // Object with __handle property
        JSValue jh_preview = JS_GetPropertyStr(ctx, argv[2], "__handle");
        if (!JS_IsUndefined(jh_preview)) {
            int64_t h_preview; JS_ToInt64(ctx, &h_preview, jh_preview);
            Object* obj_preview = qjs_ctx->get_object_registry()->get_object(h_preview);
            arg_preview = reinterpret_cast<Control*>(obj_preview);
        }
        JS_FreeValue(ctx, jh_preview);
    }

    typed_obj->force_drag(arg_data, arg_preview);
    return JS_UNDEFINED;
}

